import { after } from 'next/server';
import { logPageView } from './lib/analytics';

export default function Home() {
  // Schedule analytics logging after the response is sent - does not block the response
  after(() => {
    logPageView('/');
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting! Your page view has been logged.</p>
    </main>
  );
}

